 "content": "from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    # Each non-8 rectangle is a field; its colored motif determines the tile.
    for sr in range(h):
        for sc in range(w):
            if g[sr][sc] == 8 or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            cells = []
            colors = set()
            while q:
                r, c = q.popleft()
                cells.append((r, c))
                if g[r][c] != 0:
                    colors.add(g[r][c])
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and g[nr][nc] != 8 and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            if len(colors) != 1:
                continue
            color = next(iter(colors))
            colored = [(r,c) for r,c in cells if grid[r][c] == color]
            r0, r1 = min(r for r,c in colored), max(r for r,c in colored)
            c0, c1 = min(c for r,c in colored), max(c for r,c in colored)
            th, tw = r1-r0+1, c1-c0+1
            tile = [[grid[r0+(r-r0)%th][c0+(c-c0)%tw] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
            for r,c in cells:
                g[r][c] = tile[(r-r0)%th][(c-c0)%tw]
    return g
